INSERT INTO act_eligibility_rule VALUES(1,'2.2(2)','An insured person who intends to surrender a card under subsection (1) by mailing it or by delive...','[]','Establishes the requirement for an insured person to deface their health card before surrendering it.',NULL,NULL,'The card must be defaced in a manner approved by the General Manager before surrender.','L284-L286','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(2,'2.2(2)','The General Manager may require a person to submit any information, evidence or documents that th...','[]','The General Manager may require submission of information or documents to determine insured person status.',NULL,NULL,'The General Manager can request original documents or allow copies.','L287-L287','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(3,'2.2(4)','REVOKED:','[]','Establishes the in-patient and out-patient hospital services that an insured person is entitled to without charge.',NULL,NULL,'Services include accommodation, nursing, diagnostic procedures, prescribed drugs, and use of operating facilities. Proprietary medicines are excluded.','L298-L309','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(5,'8.1(2)','Despite subparagraph ii of paragraph 5 of subsection (1)','[{"key": "medication", "op": "is", "value": "listed in Column 1 of the Table"}, {"key": "prescription", "op": "is", "value": "by a physician on the medical staff of the hospital"}, {"key": "patient_condition", "op": "is", "value": "specific medical condition as described in Column 2 of the Table"}]','Out-patient services for specific medications are provided to insured persons without charge under certain conditions.',NULL,NULL,'Medications must be provided in Ontario hospitals and are specific to certain medical conditions.','L328-L380','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(6,'8.1(3)','Despite subparagraph iv of paragraph 5 of subsection (1)','[{"key": "service_type", "op": "equals", "value": "rabies vaccine administration"}, {"key": "medication", "op": "listed_in", "value": "Column 1 of the Table to subsection (2)"}, {"key": "conditions_met", "op": "satisfied", "value": "Column 2 of the Table"}]','Establishes that certain out-patient hospital visits are covered for insured persons without charge.',NULL,NULL,'This section specifies exceptions to the general rules regarding out-patient services.','L381-L383','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(8,'8.1(2)','Subject to section 10 and subsection 11 (1)','[{"key": "hospital", "op": "listed_in", "value": "Schedule 1"}, {"key": "service_type", "op": "includes", "value": "in-patient and out-patient services"}, {"key": "accommodation", "op": "includes", "value": "standard or public ward level"}]','An insured person is entitled to receive in-patient and out-patient services in a listed hospital without charge.',NULL,NULL,'Subject to section 10 and subsection 11 (1) of the Act.','L392-L394','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(9,'8.1(4)','Subject to section 10 and to subsection 11 (1), an insured person is entitled to receive, in a ho...','[{"key": "hospital", "op": "listed_in", "value": "Schedule 4"}, {"key": "services", "op": "in accordance with", "value": "type of care and treatment designated in the Schedule"}]','An insured person is entitled to receive insured hospital services without charge at designated hospitals.',NULL,NULL,'Subject to section 10 and subsection 11 (1).','L397-L397','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(10,'8.1(5)','Subject to subsection 11 (2), an insured person is entitled to receive, as an out-patient in a re...','[{"key": "centre_type", "op": "equals", "value": "rehabilitation centre"}, {"key": "centre_type", "op": "equals", "value": "crippled children\u2019s centre"}, {"key": "listed_in_schedule", "op": "equals", "value": "Schedule 6"}]','An insured person is entitled to receive insured outpatient services at specific rehabilitation or crippled children''s centres without charge.',NULL,NULL,'Subject to subsection 11 (2), which may impose additional conditions.','L398-L398','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(11,'8.1(6)','Subject to subsection 11 (1), an insured person is entitled to receive computerized axial tomogra...','[]','An insured person is entitled to receive computerized axial tomography scanning services in a Group M hospital without charge.',NULL,NULL,'This entitlement is subject to subsection 11 (1).','L399-L399','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(12,'8.1(8)','It is a condition of payment by the Plan to a hospital for the performance of a computerized axia...','[{"key": "hospital_grade", "op": "equals", "value": "Group M"}, {"key": "scan_location", "op": "equals", "value": "hospital premises"}]','Establishes conditions for payment by the Plan for computerized axial tomography scans.',NULL,NULL,'Payment is contingent upon the scan being performed at a specifically graded hospital.','L401-L402','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(13,'8.1(10)','This section does not apply with respect to,','[{"key": "age", "op": "<", "value": 18}, {"key": "benefit_status", "op": "in", "value": ["General Welfare Assistance Act", "Family Benefits Act", "Ontario Disability Support Program Act", "Ontario Works Act"]}]','Excludes certain individuals from the application of this section regarding insured hospital services.',NULL,NULL,'This section specifically outlines exclusions for children under 18 and individuals receiving specific forms of income support prior to hospital admission.','L425-L427','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(14,'8.1(15)','The Minister may publish the adjusted amounts on a government website','[{"key": "persons_receiving_chronic_care_services", "op": "equals", "value": "various categories based on income and dependants"}, {"key": "threshold_income_amount", "op": "not_applicable", "value": ""}, {"key": "maximum_daily_co_payment", "op": "greater_than", "value": "0"}, {"key": "maximum_monthly_co_payment", "op": "greater_than", "value": "0"}]','The Minister may publish adjusted co-payment amounts for chronic care services on a government website.',12,NULL,'Co-payment amounts are subject to annual adjustments and rounding rules.','L449-L496','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(15,'8.1(2)','An insured person is not entitled to receive insured services in a centre listed in Schedule 6 un...','[{"key": "centre", "op": "listed_in", "value": "Schedule 6"}, {"key": "examination_status", "op": "received_and_examined", "value": "out-patient"}, {"key": "referral_status", "op": "referred_by", "value": "physician"}]','An insured person is not entitled to receive insured services in a specified centre unless certain conditions are met.',NULL,NULL,'The section specifies conditions under which insured services can be accessed in certain centres.','L497-L507','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(16,'8.1(6)','The co-payment prescribed in subsections (1) and (2) does not apply to a person,','[{"key": "benefits_received", "op": "in", "value": ["Family Benefits Act", "Ontario Disability Support Program Act, 1997", "Ontario Works Act, 1997"]}, {"key": "transfer_status", "op": "in", "value": ["hospital_to_hospital", "hospital_to_Schedule_6", "hospital_to_Schedule_8", "hospital_to_medical_laboratory", "hospital_to_radiological_facility", "hospital_to_same_hospital_part", "receiving_professional_service", "receiving_equivalent_service", "admitted_to_psychiatric_facility", "resident_of_special_care_home", "resident_of_long_term_care_home"]}]','Exempts certain individuals from co-payment for insured ambulance services.',NULL,NULL,'Co-payment does not apply to individuals under specific conditions related to transfers and benefits.','L511-L525','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(18,'15.1(5)','The amount payable by the Plan for a service set out in Column 1 of Part I, II or III of the sche...','[{"key": "service_type", "op": "equals", "value": "dental surgeon or oral and maxillofacial surgeon"}, {"key": "service_date", "op": "between", "value": "April 1, 2002 and December 31, 2003"}]','Establishes payment amounts for dental services based on the type of surgeon and service date.',12,'{"prior_presence_days": 0}','Payment calculations vary based on the period in which services were rendered.','L537-L554','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(19,'15.1(3)','The maximum amount payable by the Plan for the services set out in subsection (2), excluding radi...','[]','Establishes the maximum amount payable by the Plan for specified health care services.',12,NULL,'The maximum amount excludes radiographic examinations.','L593-L593','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(20,'15.1(4)','The maximum amount payable by the Plan for radiographic examinations set out in subsection (2) an...','[]','Establishes the maximum amount payable by the Plan for radiographic examinations.',12,NULL,'The maximum amount payable for radiographic examinations is $30 within a 12-month period.','L594-L594','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(21,'15.1(5)','For the purposes of subsections (3) and (4), the 12-month period to which the maximum amount appl...','[{"key": "service_rendered_date", "op": ">=", "value": "1990-07-01"}, {"key": "test_authorization", "op": "exists", "value": "approved by physician or authorized health professional"}, {"key": "test_location", "op": "not_in", "value": "hospital laboratory"}]','Establishes the 12-month period for maximum amount applicability for specified health care services.',12,NULL,'The 12-month period begins on July 1 and ends on June 30 of the following year.','L595-L603','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(22,'22.2(4)','For the purposes of section 29,','[{"key": "hospital_approval", "op": "equals", "value": "approved by the General Manager"}, {"key": "hospital_license", "op": "equals", "value": "licensed by governmental authority"}, {"key": "service_entitlement", "op": "equals", "value": "entitled without charge in Ontario"}, {"key": "in_patient_admission", "op": "equals", "value": "ordinarily admitted to public hospital"}, {"key": "information_provision", "op": "equals", "value": "provides required information to General Manager"}, {"key": "service_type", "op": "not_equals", "value": "domiciliary type of care"}]','Establishes the definition of preferred provider arrangements and conditions for insured services rendered outside Ontario.',NULL,NULL,'Services must be rendered in a hospital outside Ontario but within Canada and meet specific criteria.','L761-L771','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(23,'28.3(1)','In-patient services rendered outside Canada in an eligible hospital or health facility are prescr...','[{"key": "services_medically_necessary", "op": "equals", "value": true}, {"key": "services_in_patient_basis", "op": "equals", "value": true}, {"key": "services_ordinarily_admitted_in_Ontario", "op": "equals", "value": true}, {"key": "services_treating_condition", "op": "equals", "value": "acute and unexpected"}, {"key": "condition_arose_outside_Canada", "op": "equals", "value": true}, {"key": "condition_requires_immediate_treatment", "op": "equals", "value": true}]','In-patient services rendered outside Canada in an eligible hospital or health facility are prescribed as insured services under specific conditions.',NULL,NULL,'Services rendered as part of domiciliary care in Ontario long-term care homes are not insured.','L833-L854','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(24,'28.3(2)','In subsection (1),','[{"key": "hospital_license", "op": "is", "value": "licensed or approved by the government"}, {"key": "procedure_type", "op": "is", "value": "complex medical and complex surgical procedures"}, {"key": "jurisdiction", "op": "is", "value": "where the hospital or health facility is situated"}]','Defines what constitutes an eligible hospital or health facility for out of country services.',NULL,NULL,'Eligibility is based on the licensing and the type of procedures performed.','L841-L844','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(25,'28.4(1)','In this section,','[{"key": "service_type", "op": "equals", "value": "medically necessary"}, {"key": "service_acceptance", "op": "equals", "value": "generally accepted by the medical profession in Ontario"}, {"key": "service_availability", "op": "either", "value": "not performed in Ontario or necessary to avoid delay"}]','Defines terms related to emergency and urgent circumstances for out-of-country services and establishes conditions under which these services are insured.',NULL,NULL,'Services rendered outside Canada are insured only under specific medical circumstances and conditions.','L855-L921','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(26,'28.4(2)','Services that are rendered outside Canada at a hospital or health facility are prescribed as insu...','[{"key": "service_acceptance", "op": "is", "value": "generally accepted by the medical profession in Ontario"}, {"key": "medical_necessity", "op": "is", "value": "medically necessary"}, {"key": "service_availability", "op": "is_not", "value": "identical or equivalent service performed in Ontario"}, {"key": "service_delay", "op": "is", "value": "necessary to avoid delay resulting in death or significant irreversible damage"}, {"key": "entitlement", "op": "is", "value": "entitled without charge for in-patient or out-patient service"}, {"key": "hospital_admission", "op": "is", "value": "ordinarily admitted to a public hospital as an in-patient"}]','Services rendered outside Canada at a hospital or health facility are prescribed as insured services under specific conditions.',NULL,NULL,'Services must meet all specified conditions to be considered insured when rendered outside Canada.','L867-L874','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(27,'28.4(5)','For the purposes of clause (2) (c)','[{"key": "service_type", "op": "includes", "value": "insured services"}, {"key": "funding_status", "op": "includes", "value": "publicly funded"}, {"key": "availability", "op": "includes", "value": "for sale in Ontario"}, {"key": "eligibility", "op": "includes", "value": "eligible under programs or policies"}]','Defines what constitutes a service performed in Ontario for the purposes of clause (2)(c).',NULL,NULL,'Services must be legally obtainable in Ontario and can include various types of funding and eligibility criteria.','L887-L891','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(28,'28.6(1)','For in-patient services, it is a condition of the payment of any amount under section 28','[{"key": "service_type", "op": "equals", "value": "in-patient"}, {"key": "service_type", "op": "equals", "value": "out-patient"}, {"key": "written_statement", "op": "required", "value": "from hospital or health facility"}]','Establishes conditions for payment of in-patient and out-patient services under specified sections.',NULL,'{"prior_presence_days": 0}','Written statements must include specific details about admission, diagnosis, treatment, and discharge.','L934-L1010','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(29,'28.6(2)','REVOKED:','[]','Establishes that only designated hospitals and health facilities are entitled to payment for insured services provided to insured persons.',NULL,NULL,'Only hospitals designated under the Act and this Regulation can receive payment for insured services.','L976-L985','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(30,'37.1(1)','A service rendered by a physician in Ontario is an insured service if','[{"key": "physician_membership", "op": "is", "value": "member of the College of Physicians and Surgeons of Ontario or exempt"}, {"key": "location", "op": "is", "value": "both physician and insured person are in Ontario"}, {"key": "service_type", "op": "is", "value": "listed in the schedule of benefits"}]','A service rendered by a physician in Ontario is insured if specific conditions are met.',NULL,'{"prior_presence_days": 0}','The basic fee for an insured service is determined by the schedule of benefits.','L1011-L1089','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(31,'37.1(2)','The basic fee payable by the Plan for an insured service described in subsection (1) is the fee p...','[{"key": "service_type", "op": "equals", "value": "diagnostic service"}, {"key": "service_location", "op": "equals", "value": "Ontario"}, {"key": "service_rendered_date", "op": "between", "value": "April 1, 2001 and March 31, 2006"}, {"key": "patient_status", "op": "in", "value": ["inpatient", "emergency department patient", "day care patient"]}]','Establishes the basic fee payable by the Plan for insured diagnostic services as per the schedule of benefits.',24,'{"prior_presence_days": 0}','Diagnostic services rendered to certain patients may have specific payment conditions and deadlines for account submission.','L1015-L1065','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(32,'37.6(1)','The basic fee payable for an insured service rendered by a physician in Ontario, as set out in th...','[{"key": "service_rendered_date", "op": ">=", "value": "April 1, 2004"}, {"key": "service_listed_in_publication", "op": "exists", "value": "List of Family Practice Professional Fees or List of Specialist Practice Professional Fees"}]','Increases the basic fee for insured physician services in Ontario based on specific conditions.',NULL,NULL,'The fee increase is 2.5% for family practice services and 2% for specialist services.','L1099-L1104','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(33,'37.6(2)','The basic fee payable for an insured service rendered by a physician in Ontario','[{"key": "service_date", "op": ">=", "value": "April 1, 2004"}, {"key": "service_listing", "op": "exists_in", "value": "List of Specialist Practice Professional Fees"}]','The basic fee for insured services rendered by a physician in Ontario is increased by 2 percent under specific conditions.',NULL,NULL,'The increase applies only to services listed in a specific publication by the Ministry of Health and Long-Term Care.','L1102-L1104','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(34,'37.7','The basic fee payable for an insured service rendered by a physician in Ontario','[{"key": "service_date", "op": ">=", "value": "April 1, 2005"}, {"key": "service_listing", "op": "exists_in", "value": "List of Technical Fees"}]','Increases the basic fee for insured physician services by 1% under specific conditions.',NULL,NULL,'The increase applies only to services listed in the specified publication.','L1105-L1107','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(35,'37.8','Sections 37','[{"key": "service_rendered_date", "op": "between", "value": "April 1, 2022 and April 1, 2023"}, {"key": "service_rendered_date", "op": "between", "value": "April 1, 2024 and April 1, 2025"}, {"key": "service_rendered_date", "op": "between", "value": "April 1, 2025 and April 1, 2026"}, {"key": "fee_type", "op": "not_equal", "value": "H fees"}]','Establishes fee increases for insured physician services rendered in Ontario during specified periods.',12,NULL,'H fees are excluded from the fee increases as defined in the schedule of benefits.','L1108-L1122','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(36,'37.8(3)','In this section,','[{"key": "service_rendered_date", "op": "between", "value": "April 1, 2025 and April 1, 2026"}, {"key": "location", "op": "equals", "value": "Ontario"}]','Establishes the fee increase for insured physician services in Ontario for a specific period.',12,NULL,'The fee increase is based on a specific document published by the Ministry of Health.','L1119-L1122','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(37,'38.6(12)','This section does not apply to any action arising out of negligence or other wrongful act or omis...','[{"key": "accident_date", "op": "after", "value": "1978-11-30"}, {"key": "motor_vehicle_insurance", "op": "insured", "value": "true"}, {"key": "motor_vehicle_permit", "op": "issued", "value": "true"}]','This section excludes certain actions arising from negligence or wrongful acts related to motor vehicle operation from its application.',NULL,NULL,'This section specifically pertains to actions involving motor vehicles and does not apply to negligence claims.','L1283-L3669','2025-09-23 17:44:39');
INSERT INTO act_eligibility_rule VALUES(92,'1.1','Amendments dated May 12, 2006','{"description": "This section lists amendments to the Health Insurance Act made on various dates.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": []}','This section lists amendments to the Health Insurance Act made on various dates.',NULL,NULL,'This section does not contain eligibility or residency rules.','L129-L140','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(93,'1.1','For the purposes of subsection 11 (2','{"description": "Defines terms related to dependants and members of the Canadian Forces for health insurance eligibility.", "conditions": [{"key": "dependant_age", "op": "<", "value": 22}, {"key": "dependant_disability", "op": "exists", "value": "true"}, {"key": "member_of_canadian_forces", "op": "exists", "value": "true"}], "durations": {}, "prerequisites": {}, "actors": ["dependant", "member_of_canadian_forces", "spouse"]}','Defines terms related to dependants and members of the Canadian Forces for health insurance eligibility.',NULL,NULL,'Dependants include children under 22 or those over 22 with disabilities. Definitions for spouse are referenced from another regulation.','L196-L203','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(94,'1.2','For the purposes of the Act and any regulation made under the Act, and despite any other meaning ...','{"description": "Defines the term ''resident'' for the purposes of the Act and regulations, establishing criteria for residency.", "conditions": [{"key": "primary_place_of_residence", "op": "ceases_to_be", "value": "Ontario"}, {"key": "sections", "op": "must_be_described_in", "value": "1.3 to 1.14"}], "durations": {}, "prerequisites": {}, "actors": ["resident"]}','Defines the term ''resident'' for the purposes of the Act and regulations, establishing criteria for residency.',NULL,NULL,'A person ceases to be a resident if their primary place of residence is no longer Ontario, unless specific subsections apply.','L204-L204','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(95,'1.3','Upon application to be an insured person','{"description": "Establishes requirements for a person to be considered a resident and insured person in Ontario.", "conditions": [{"key": "eligible_status", "op": "must possess", "value": "set out in section 1.4"}, {"key": "primary_place_of_residence", "op": "must be", "value": "in Ontario"}], "durations": {}, "prerequisites": {"prior_presence_days": 153}, "actors": ["insured_person", "child", "General_Manager"]}','Establishes requirements for a person to be considered a resident and insured person in Ontario.',NULL,'{"prior_presence_days": 153}','Children under 16 are considered to have the primary residence of the person with lawful custody. Inmates and children in care are recognized as residents regardless of other requirements.','L205-L210','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(96,'1.4','A person cannot be recognized as a resident','{"description": "Establishes the eligible statuses for a person to be recognized as a resident for health insurance purposes.", "conditions": [{"key": "status", "op": "in", "value": ["Canadian citizen", "landed immigrant", "permanent resident", "registered Indian", "protected person", "applicant for permanent residence", "work permit holder", "self-employed", "member of clergy", "spouse or dependant", "temporary resident permit holder"]}, {"key": "employment", "op": "exists", "value": "full-time agreement in Ontario"}, {"key": "duration", "op": "greater_than_or_equal_to", "value": 6}], "durations": {"months": 6, "repeatable": false}, "prerequisites": {}, "actors": ["resident", "spouse", "dependant", "clergy", "worker"]}','Establishes the eligible statuses for a person to be recognized as a resident for health insurance purposes.',NULL,NULL,'Eligibility includes various statuses such as citizenship, immigration status, and specific employment conditions.','L215-L231','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(97,'1.5','The following requirements must be met for a person to be continued to be recognized as a resident:','{"description": "Establishes requirements for a person to be recognized as a resident for health insurance purposes.", "conditions": [{"key": "physical_presence_days", "op": ">=", "value": 153}, {"key": "primary_residence", "op": "==", "value": "Ontario"}, {"key": "eligible_status", "op": "exists", "value": "true"}], "durations": {"months": 12, "repeatable": true}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "mobile_student", "mobile_worker", "spouse", "dependant"]}','Establishes requirements for a person to be recognized as a resident for health insurance purposes.',NULL,'{"prior_presence_days": 153}','Exemptions apply for certain individuals such as mobile students, mobile workers, and military dependants. A child under 16 is considered to have the primary residence of the custodian.','L232-L242','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(98,'1.6','A resident is considered to meet the physical presence requirement for up to 12 full months, if h...','{"description": "Establishes the physical presence requirement for residents temporarily leaving Ontario.", "conditions": [{"key": "physical_presence", "op": "greater_than_or_equal_to", "value": 153}, {"key": "status", "op": "in", "value": ["mobile_student", "mobile_worker"]}], "durations": {"months": 12, "repeatable": false}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "mobile_student", "mobile_worker"]}','Establishes the physical presence requirement for residents temporarily leaving Ontario.',NULL,'{"prior_presence_days": 153}','The section outlines conditions under which a resident can maintain residency status while temporarily absent from Ontario.','L243-L248','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(99,'1.7','A resident is considered to meet the physical presence requirement during a maximum of five 12-mo...','{"description": "Establishes conditions under which a resident can meet the physical presence requirement while working or serving outside Canada.", "conditions": [{"key": "employment_status", "op": "equals", "value": "full-time"}, {"key": "location", "op": "equals", "value": "outside Canada"}, {"key": "type_of_service", "op": "equals", "value": "charity"}, {"key": "physical_presence", "op": "greater_than_or_equals", "value": 153}], "durations": {"months": 12, "repeatable": true}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "mobile_student", "mobile_worker"]}','Establishes conditions under which a resident can meet the physical presence requirement while working or serving outside Canada.',NULL,'{"prior_presence_days": 153}','The provision applies for a maximum of five 12-month periods.','L249-L252','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(100,'1.8','A resident who goes to another province or territory of Canada to attend as a student one or more...','{"description": "Defines conditions under which a resident attending school outside Ontario is considered to meet physical presence requirements for health insurance.", "conditions": [{"key": "enrollment_status", "op": "equals", "value": "full-time"}, {"key": "location", "op": "in", "value": "another province or territory of Canada"}, {"key": "physical_presence", "op": "greater_than_or_equal_to", "value": 153}, {"key": "time_period", "op": "equals", "value": "12 months"}], "durations": {"months": 12, "repeatable": true}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "student"]}','Defines conditions under which a resident attending school outside Ontario is considered to meet physical presence requirements for health insurance.',NULL,'{"prior_presence_days": 153}','The physical presence requirement can be met through various combinations of being physically present in Ontario, being a mobile student or worker, or maintaining residency.','L253-L262','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(101,'1.9','A resident who leaves Ontario is considered to meet the physical presence requirement during the ...','{"description": "A resident who leaves Ontario is considered to meet the physical presence requirement if they are receiving insured services that have been approved for payment.", "conditions": [{"key": "insured_services", "op": "required", "value": "approved payment"}, {"key": "application_for_payment", "op": "required", "value": "submitted by General Manager"}], "durations": {}, "prerequisites": {}, "actors": ["resident"]}','A resident who leaves Ontario is considered to meet the physical presence requirement if they are receiving insured services that have been approved for payment.',NULL,NULL,'This clause allows residents to maintain their eligibility for health insurance while temporarily outside Ontario for approved medical services.','L263-L263','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(102,'1.10','A resident who is a member of the Canadian Forces or Royal Canadian Mounted Police or who is a Ca...','{"description": "Establishes that certain residents maintain physical presence status while posted outside Canada.", "conditions": [{"key": "status", "op": "equals", "value": "member of Canadian Forces or Royal Canadian Mounted Police or Canadian diplomat"}, {"key": "prior_residency", "op": "equals", "value": "resident immediately before leaving for posting"}], "durations": {}, "prerequisites": {}, "actors": ["resident", "member of Canadian Forces", "Royal Canadian Mounted Police", "Canadian diplomat"]}','Establishes that certain residents maintain physical presence status while posted outside Canada.',NULL,NULL,'Physical presence requirement is considered met during postings outside Canada.','L264-L264','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(103,'1.11','In addition to the other circumstances in which a resident is also considered to meet the physica...','{"description": "Establishes conditions under which a resident traveling outside Ontario is considered to meet the physical presence requirement.", "conditions": [{"key": "physical_presence_in_Ontario", "op": "greater_than_or_equal_to", "value": 153}, {"key": "mobile_student_or_worker", "op": "exists", "value": "true"}], "durations": {"months": 24, "repeatable": true}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "mobile_student", "mobile_worker"]}','Establishes conditions under which a resident traveling outside Ontario is considered to meet the physical presence requirement.',NULL,'{"prior_presence_days": 153}','Subsection (1) can only apply once unless the resident meets the physical presence requirement for at least 153 days in five consecutive 12-month periods before each subsequent application.','L265-L268','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(104,'1.12','A resident who is the spouse or a dependant of someone who continues to be a resident under secti...','{"description": "Defines conditions under which a spouse or dependant is considered to meet the physical presence requirement while accompanying a resident in various circumstances.", "conditions": [{"key": "relationship", "op": "equals", "value": "spouse or dependant"}, {"key": "accompanying", "op": "equals", "value": "resident under sections 1.7, 1.8, 1.9, or 1.10"}], "durations": {}, "prerequisites": {"prior_presence_days": 153}, "actors": ["resident", "spouse", "dependant"]}','Defines conditions under which a spouse or dependant is considered to meet the physical presence requirement while accompanying a resident in various circumstances.',NULL,'{"prior_presence_days": 153}','The spouse or dependant must have met the applicable requirements under the relevant sections before accompanying the resident.','L269-L271','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(105,'1.13','A resident is considered to meet the physical presence requirement during any period of time wher...','{"description": "Establishes that a resident meets the physical presence requirement if unable to return to Ontario due to unlawful activity by another person.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": ["resident"]}','Establishes that a resident meets the physical presence requirement if unable to return to Ontario due to unlawful activity by another person.',NULL,NULL,'This clause provides an exception to the physical presence requirement based on unlawful actions preventing return.','L272-L272','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(106,'1.14','A resident is considered to meet the physical presence requirement during any period of time wher...','{"description": "A resident is considered to meet the physical presence requirement while being a mobile student or worker outside of Ontario.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": ["resident", "mobile_student", "mobile_worker"]}','A resident is considered to meet the physical presence requirement while being a mobile student or worker outside of Ontario.',NULL,NULL,'This section clarifies that mobile students and workers are exempt from the physical presence requirement while outside Ontario.','L273-L278','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(107,'2.1','Children who are receiving services and supports by agreement with a children’s aid society under...','{"description": "Establishes eligibility for health card coverage for specific groups of children and young persons under certain conditions.", "conditions": [{"key": "agreement_with_children_aid_society", "op": "exists", "value": "true"}, {"key": "detained_or_committed", "op": "exists", "value": "true"}, {"key": "work_permit", "op": "exists", "value": "true"}, {"key": "emergency_authorization", "op": "exists", "value": "true"}], "durations": {}, "prerequisites": {}, "actors": ["children", "young_persons", "workers", "persons_with_emergency_authorization"]}','Establishes eligibility for health card coverage for specific groups of children and young persons under certain conditions.',NULL,NULL,'Eligibility includes children receiving services from children''s aid societies, young persons in detention, seasonal agricultural workers, and individuals with humanitarian emergency authorizations.','L211-L214','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(108,'2.1','REVOKED:','{"description": "This section has been revoked and is no longer in effect.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": []}','This section has been revoked and is no longer in effect.',NULL,NULL,'No further details are applicable as the section is revoked.','L279-L279','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(109,'2.1','The use of occupational therapy and physiotherapy facilities where available in a hospital in Can...','{"description": "Establishes coverage for various therapy and medical services when prescribed by authorized healthcare professionals in hospitals in Canada.", "conditions": [{"key": "prescription", "op": "required", "value": "physician or registered nurse in the extended class"}, {"key": "location", "op": "must be", "value": "hospital in Canada"}], "durations": {}, "prerequisites": {}, "actors": ["physician", "registered_nurse_extended_class", "oral_and_maxillofacial_surgeon", "midwife"]}','Establishes coverage for various therapy and medical services when prescribed by authorized healthcare professionals in hospitals in Canada.',NULL,NULL,'Excludes proprietary medicines, home medications, diagnostic services for third parties, and visits solely for drug administration.','L310-L320','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(110,'2.2','The following information is prescribed as personal information that may be collected','{"description": "Establishes the types of personal information that may be collected, used, or disclosed under the Act.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": ["insured_person"]}','Establishes the types of personal information that may be collected, used, or disclosed under the Act.',NULL,NULL,'Includes a photograph and signature of the insured person.','L280-L282','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(111,'2.3(1)','An insured person shall surrender his or her health card to the General Manager upon ceasing to b...','{"description": "An insured person must surrender their health card upon ceasing to be a resident.", "conditions": [{"key": "status", "op": "equals", "value": "ceasing to be a resident"}, {"key": "submission_method", "op": "in", "value": ["mail", "delivery other than personal"]}], "durations": {}, "prerequisites": {"prior_presence_days": 153}, "actors": ["insured_person", "General Manager"]}','An insured person must surrender their health card upon ceasing to be a resident.',NULL,'{"prior_presence_days": 153}','The health card must be defaced in an approved manner before surrendering if not delivered personally.','L283-L287','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(112,'3.1','REVOKED:','{"description": "Establishes the application process for entitlement to be an insured person and outlines the rules for submitting applications on behalf of others.", "conditions": [{"key": "application_form", "op": "approved_by", "value": "General Manager"}, {"key": "submission_method", "op": "specified_by", "value": "General Manager"}, {"key": "age", "op": "less_than", "value": 16}, {"key": "incapacity", "op": "exists", "value": "reasonable grounds"}, {"key": "deceased", "op": "status", "value": "estate trustee or responsible person"}], "durations": {}, "prerequisites": {}, "actors": ["insured_person", "parent", "children''s_aid_society", "estate_trustee", "authorized_person"]}','Establishes the application process for entitlement to be an insured person and outlines the rules for submitting applications on behalf of others.',NULL,NULL,'The General Manager may require in-person submission and additional documentation for applications made on behalf of others.','L288-L309','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(113,'7.1','Use of home hyperalimentation equipment and supplies where available in a hospital in Ontario and...','{"description": "Allows the use of home hyperalimentation equipment and supplies in Ontario hospitals when prescribed by authorized medical staff.", "conditions": [{"key": "equipment_type", "op": "equals", "value": "home hyperalimentation"}, {"key": "prescriber", "op": "equals", "value": "physician or registered nurse in extended class"}, {"key": "location", "op": "equals", "value": "hospital in Ontario"}], "durations": {}, "prerequisites": {}, "actors": ["physician", "registered_nurse", "haemophiliac_patient"]}','Allows the use of home hyperalimentation equipment and supplies in Ontario hospitals when prescribed by authorized medical staff.',NULL,NULL,'Equipment and supplies must be available in the hospital.','L321-L322','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(114,'8.1','The provision to haemophiliac patients, for use in the home, of equipment and supplies other than...','{"description": "Provision of home-use equipment and supplies for haemophiliac patients, prescribed by a registered nurse.", "conditions": [{"key": "equipment_and_supplies_available_in_hospital", "op": "equals", "value": "true"}, {"key": "prescribed_by_registered_nurse", "op": "equals", "value": "true"}], "durations": {}, "prerequisites": {}, "actors": ["haemophiliac_patient", "registered_nurse"]}','Provision of home-use equipment and supplies for haemophiliac patients, prescribed by a registered nurse.',NULL,NULL,'Equipment and supplies must be available in a hospital in Ontario.','L323-L383','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(115,'8.1','Despite paragraph 3 of section 7 and paragraph 1 of subsection 8 (1)','{"description": "Establishes conditions under which laboratory, radiological, or other diagnostic procedures ordered by an oral and maxillofacial surgeon are covered as insured hospital services.", "conditions": [{"key": "procedure_type", "op": "equals", "value": "diagnostic"}, {"key": "surgeon_type", "op": "equals", "value": "oral and maxillofacial"}, {"key": "hospital_service_type", "op": "in", "value": ["in-patient", "out-patient"]}, {"key": "medical_necessity", "op": "equals", "value": "true"}], "durations": {}, "prerequisites": {}, "actors": ["insured_person", "oral_and_maxillofacial_surgeon", "hospital"]}','Establishes conditions under which laboratory, radiological, or other diagnostic procedures ordered by an oral and maxillofacial surgeon are covered as insured hospital services.',NULL,NULL,'Coverage is contingent upon the procedures being medically necessary and related to dental surgical procedures.','L384-L525','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(116,'8.1','The production or completion of a document, or the transmission of information to any person othe...','{"description": "Allows for the production or completion of documents and transmission of information required by government legislation for insured persons.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": ["insured_person"]}','Allows for the production or completion of documents and transmission of information required by government legislation for insured persons.',NULL,NULL,'This section pertains to the requirements for documentation and information transmission related to government programs.','L653-L653','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(117,'8.1','If the service is a diagnostic procedure that is listed under “Diagnostic and Therapeutic Procedu...','{"description": "Establishes requirements for identification numbers and service site indicators for various diagnostic and therapeutic procedures covered under the Ontario Health Insurance Plan.", "conditions": [{"key": "service_type", "op": "equals", "value": "diagnostic procedure"}, {"key": "service_type", "op": "equals", "value": "consultation"}, {"key": "service_type", "op": "equals", "value": "assessment"}, {"key": "service_location", "op": "equals", "value": "mobile integrated community health services centre"}, {"key": "patient_status", "op": "equals", "value": "in-patient"}], "durations": {}, "prerequisites": {}, "actors": ["referring_physician", "registered_nurse", "midwife", "aboriginal_midwife", "patient"]}','Establishes requirements for identification numbers and service site indicators for various diagnostic and therapeutic procedures covered under the Ontario Health Insurance Plan.',NULL,NULL,'Identification numbers are required for referring physicians, registered nurses, and midwives based on the type of service provided.','L1216-L1220','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(118,'8.2','The production or completion of a document','{"description": "Defines services that are not covered under the insured hospital services in Canada.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": ["insured_person"]}','Defines services that are not covered under the insured hospital services in Canada.',NULL,NULL,'This section outlines exclusions from coverage, including various medical and non-medical services.','L654-L1215','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(119,'9.1','Amendments dated November 22, 2007 (effective as of February 1, 2008)','{"description": "This section outlines various amendments to the insured hospital services regulations, detailing effective dates for each amendment.", "conditions": [], "durations": {}, "prerequisites": {}, "actors": []}','This section outlines various amendments to the insured hospital services regulations, detailing effective dates for each amendment.',NULL,NULL,'The section primarily lists amendments and their effective dates without specifying conditions or actors.','L141-L195','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(120,'12.1','If it is required by the Ontario Health Insurance Plan, the master number specified by the Plan f...','{"description": "Establishes requirements for claims related to insured hospital services in Ontario, including necessary identifiers and codes.", "conditions": [{"key": "service_rendered", "op": "required", "value": "hospital"}, {"key": "service_type", "op": "required", "value": "in-patient, out-patient, day surgery, emergency department"}, {"key": "claimant_insurance", "op": "required", "value": "insured by another province or territory"}], "durations": {}, "prerequisites": {"prior_presence_days": 0}, "actors": ["insured_person", "physician", "medical_director", "oral_and_maxillofacial_surgeon"]}','Establishes requirements for claims related to insured hospital services in Ontario, including necessary identifiers and codes.',NULL,'{"prior_presence_days": 0}','Claims must include specific identifiers and codes as outlined by the Ontario Health Insurance Plan.','L1221-L3669','2025-09-23 18:15:48');
INSERT INTO act_eligibility_rule VALUES(121,'15.1(1)','Ambulance services provided in accordance with the patient care standards described in clause 11 ...','{"description": "Ambulance services are insured if provided by a certified operator and a co-payment is made by the insured person.", "conditions": [{"key": "ambulance_service_operator_certificate", "op": "equals", "value": "certified"}, {"key": "co_payment", "op": "equals", "value": "$45"}, {"key": "associated_hospital", "op": "defined_in", "value": "Public Hospitals Act"}], "durations": {}, "prerequisites": {}, "actors": ["insured_person", "ambulance_service_operator"]}','Ambulance services are insured if provided by a certified operator and a co-payment is made by the insured person.',NULL,NULL,'Co-payment does not apply to individuals listed in subsection 15(6).','L526-L652','2025-09-23 18:15:48');
