INSERT INTO adp_funding_rule VALUES(156,'glucose_monitoring','310','purchase','25%','Clients are responsible for 25% of the approved price for Continuous Glucose Monitoring Systems.','2025-09-24 19:32:34','2025-09-24 19:32:34');
INSERT INTO adp_funding_rule VALUES(157,'glucose_monitoring','310','lease','20%','Clients are responsible for 20% of the approved price when leasing Continuous Glucose Monitoring Systems under the Continuous Eligibility Program.','2025-09-24 19:32:34','2025-09-24 19:32:34');
