INSERT INTO adp_funding_rule VALUES(967,'core_manual','220.03','Device Protection',NULL,'Clients are responsible for the protection, proper use, and care of the Devices funded by the Program.','2025-09-24 19:35:01','2025-09-24 19:35:01');
INSERT INTO adp_funding_rule VALUES(968,'core_manual','220.03','Insurance Consideration',NULL,'Clients should consider buying insurance to cover situations of loss or theft.','2025-09-24 19:35:01','2025-09-24 19:35:01');
INSERT INTO adp_funding_rule VALUES(969,'core_manual','220.04','repair',NULL,replace('funding\nfor a replacement Device may be submitted to the Program with\nsupporting documentation including a Vendor quotation stating either: Not\nRepairable – Device Lost or Not Repairable – Device Stol','\n',char(10)),'2025-09-24 19:35:02','2025-09-24 19:35:02');
INSERT INTO adp_funding_rule VALUES(970,'core_manual','220.04','replacement Device funding',NULL,'Funding for a replacement Device may be submitted to the Program with supporting documentation including a Vendor quotation stating either: Not Repairable – Device Lost or Not Repairable – Device Stolen. The Program will assist with funding a replacement Device if the eligibility criteria are met.','2025-09-24 19:35:02','2025-09-24 19:35:02');
INSERT INTO adp_funding_rule VALUES(971,'core_manual','220.05','repair',NULL,replace('The Program provides funding assistance to replace a previously funded\nDevice that is damaged due to normal use or wear, either during or after\nthe designated funding period, where:\n•\nthe Device is no','\n',char(10)),'2025-09-24 19:35:02','2025-09-24 19:35:02');
INSERT INTO adp_funding_rule VALUES(972,'core_manual','220.05','replacement due to normal wear',NULL,'Funding assistance is provided to replace a Device damaged due to normal use or wear, provided the Device is no longer under warranty and repair costs exceed one-third of the original purchase price.','2025-09-24 19:35:02','2025-09-24 19:35:02');
INSERT INTO adp_funding_rule VALUES(973,'core_manual','220.05','replacement during designated funding period',NULL,'Funding assistance for a replacement Device requested and approved during the designated funding period may be a pro-rated contribution based on the age and designated funding period of the original Device.','2025-09-24 19:35:02','2025-09-24 19:35:02');
INSERT INTO adp_funding_rule VALUES(974,'core_manual','220.06','repair',NULL,replace('with supporting documentation for consideration (e.g., Vendor or\nmanufacturer quotations for repairs, Vendor confirmation that the Device is\nnot repairable, and verification that the Device is no long','\n',char(10)),'2025-09-24 19:35:03','2025-09-24 19:35:03');
INSERT INTO adp_funding_rule VALUES(975,'core_manual','220.06','purchase',NULL,'A new application for funding must be submitted to the Program together with supporting documentation for consideration.','2025-09-24 19:35:03','2025-09-24 19:35:03');
INSERT INTO adp_funding_rule VALUES(976,'core_manual','220.07','replacement',100,'Clients are responsible for the full cost of replacing Devices damaged due to misuse or negligence.','2025-09-24 19:35:03','2025-09-24 19:35:03');
INSERT INTO adp_funding_rule VALUES(977,'core_manual','300','purchase','25%','Clients are responsible for paying 25% of the approved price for purchased items.','2025-09-24 19:35:03','2025-09-24 19:35:03');
