INSERT INTO adp_funding_rule VALUES(991,'core_manual','305.00','purchase','more than 25%','The ADP pays up to 75% of an ADP approved maximum amount. The Client may pay more than 25% of the cost of the Device, depending on the retail cost.','2025-09-24 19:35:05','2025-09-24 19:35:05');
