INSERT INTO adp_funding_rule VALUES(994,'core_manual','305.01','accessories',NULL,replace('The\namount that the Client pays may be greater depending on whether the\nApproved Price is based on a fixed amount up to a maximum contribution\nand whether the Client purchases accessories, upgrades or','\n',char(10)),'2025-09-24 19:35:06','2025-09-24 19:35:06');
