INSERT INTO odb_drugs VALUES('09858361','Dexcom G7 Receiver','GLUCOSE MONITORING SYSTEM','DEX',NULL,'Continuous Glucose Monitoring System-Receiver Kit','2386','MISCELLANEOUS','CONTINUOUS GLUCOSE MONITORING SYSTEMS','GLUCOSE_MONITORING_SYSTEM_None_Continuous_Glucose_Monitoring_System-Receiver_Kit',60.0,NULL,60.0,'2025-07-31','active',0,1,0,1,0,0,1,0,'F',replace('Reimbursement Criteria and Maximum Reimbursed Quantity:\n\nAll ODB eligible recipients on insulin therapy for diabetes who have a valid prescription from a physician or nurse practitioner for CGM sensors and/or a CGM reader/receiver designated on the Formulary are eligible to receive the prescribed ODB-funded CGM sensors and/or reader/receiver.\n\nPatients who meet the reimbursement criteria are eligible for a maximum reimbursed quantity of 45 sensors over the course of a 365-day period.\n\nPlease refer to the Ontario Drug Programs Reference Manual for more information related to CGM systems (e.g., pharmacy billing procedure, HNS response codes and messages).','\n',char(10)),'2025-09-22 17:46:29');
