PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE act_eligibility_rule (
            rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_ref TEXT NOT NULL,
            title TEXT NOT NULL,
            condition_json TEXT NOT NULL,
            effect TEXT NOT NULL,
            max_duration_months INTEGER,
            prerequisites_json TEXT,
            notes TEXT,
            line_range TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(section_ref, title)
        );
CREATE TABLE act_status_extension (
            ext_id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_ref TEXT NOT NULL,
            population TEXT NOT NULL,
            condition_json TEXT NOT NULL,
            effect TEXT NOT NULL,
            line_range TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(section_ref, population)
        );
CREATE TABLE act_dependant_carryover (
            dep_id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_ref TEXT NOT NULL,
            who TEXT NOT NULL,
            anchor_population TEXT NOT NULL,
            effect TEXT NOT NULL,
            prerequisites_json TEXT,
            line_range TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(section_ref, who, anchor_population)
        );
CREATE TABLE act_health_card_rule (
            rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_ref TEXT NOT NULL,
            obligation TEXT NOT NULL,
            scope TEXT NOT NULL,
            line_range TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(section_ref, obligation, scope)
        );
CREATE TABLE act_uninsured_reference (
            ref_id INTEGER PRIMARY KEY AUTOINCREMENT,
            act_pointer TEXT NOT NULL,
            schedule_pointer TEXT,
            exemplar TEXT NOT NULL,
            line_range TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(act_pointer, exemplar)
        );
CREATE TABLE act_ingestion_log (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_file TEXT NOT NULL,
            status TEXT NOT NULL,
            sections_processed INTEGER,
            sql_records INTEGER,
            chroma_embeddings INTEGER,
            error_count INTEGER,
            started_at TIMESTAMP,
            completed_at TIMESTAMP,
            metadata_json TEXT
        , chunks_created INTEGER DEFAULT 0);
CREATE TABLE adp_funding_rule (
  rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
  adp_doc TEXT NOT NULL,              -- 'comm_aids' | 'mobility' | 'core_manual'
  section_ref TEXT,                   -- e.g., '405.02' or 'Part 7: 705'
  scenario TEXT NOT NULL,             -- 'purchase' | 'lease' | 'repair' | 'accessories' (extend if needed)
  client_share_percent DECIMAL(5,2),  -- e.g., 25.00; NULL if N/A (e.g., lease)
  details TEXT,                       -- short narrative (CEP terms, exceptions)
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(adp_doc, section_ref, scenario)
);
CREATE TABLE adp_exclusion (
  exclusion_id INTEGER PRIMARY KEY AUTOINCREMENT,
  adp_doc TEXT NOT NULL,              -- 'comm_aids' | 'mobility' | 'core_manual'
  section_ref TEXT,                   -- if we can capture it; else NULL
  phrase TEXT NOT NULL,               -- canonicalized exclusion wording
  applies_to TEXT,                    -- optional: 'mobility','communication_aids','power_wheelchair', etc.
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(adp_doc, phrase, section_ref)
);
CREATE TABLE ohip_fee_schedule(
  fee_code TEXT,
  description TEXT,
  amount REAL,
  units TEXT,
  specialty TEXT,
  category TEXT,
  subcategory TEXT,
  requirements TEXT,
  notes TEXT,
  effective_date NUM,
  end_date NUM,
  page_number INT,
  section TEXT,
  updated_date NUM
);
CREATE TABLE odb_drugs(
  din TEXT,
  name TEXT,
  generic_name TEXT,
  manufacturer_id TEXT,
  strength TEXT,
  dosage_form TEXT,
  item_number TEXT,
  therapeutic_class TEXT,
  category TEXT,
  interchangeable_group_id TEXT,
  individual_price REAL,
  daily_cost REAL,
  amount_mohltc_pays REAL,
  listing_date NUM,
  status TEXT,
  is_lowest_cost NUM,
  is_benefit NUM,
  is_chronic_use NUM,
  is_section_3 NUM,
  is_section_3b NUM,
  is_section_3c NUM,
  is_section_9 NUM,
  is_section_12 NUM,
  additional_benefit_type TEXT,
  notes TEXT,
  updated_date NUM
);
CREATE TABLE odb_interchangeable_groups(
  group_id TEXT,
  generic_name TEXT,
  therapeutic_class TEXT,
  category TEXT,
  strength TEXT,
  dosage_form TEXT,
  item_number TEXT,
  member_count INT,
  lowest_cost_din TEXT,
  lowest_cost_price REAL,
  daily_cost TEXT,
  notes TEXT,
  updated_date NUM
);
CREATE TABLE ohip_diagnostic_codes(
  diagnostic_code TEXT,
  description TEXT,
  category TEXT,
  notes TEXT,
  updated_date NUM
);
CREATE TABLE chunk_fee_codes(
  chunk_id TEXT,
  fee_code TEXT,
  relevance_score REAL
);
CREATE TABLE document_chunks(
  chunk_id TEXT,
  source_type TEXT,
  source_document TEXT,
  chunk_text TEXT,
  chunk_index INT,
  page_number INT,
  section TEXT,
  subsection TEXT,
  start_char INT,
  end_char INT,
  embedding_model TEXT,
  embedding_id TEXT,
  metadata_json TEXT,
  created_date NUM,
  fee_codes_list TEXT,
  embedding_vector
);
CREATE TABLE ingestion_log(
  log_id INT,
  source_type TEXT,
  source_file TEXT,
  status TEXT,
  records_processed INT,
  records_failed INT,
  error_message TEXT,
  started_at NUM,
  completed_at NUM
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_act_eligibility_section ON act_eligibility_rule(section_ref);
CREATE INDEX idx_act_eligibility_title ON act_eligibility_rule(title);
CREATE INDEX idx_act_status_population ON act_status_extension(population);
CREATE INDEX idx_act_dependant_who ON act_dependant_carryover(who);
CREATE INDEX idx_act_health_card_obligation ON act_health_card_rule(obligation);
CREATE INDEX idx_act_uninsured_exemplar ON act_uninsured_reference(exemplar);
CREATE VIEW v_act_eligibility AS
        SELECT 
            rule_id,
            section_ref,
            title,
            effect,
            max_duration_months,
            condition_json,
            prerequisites_json,
            notes,
            line_range,
            CASE 
                WHEN title LIKE '%student%' THEN 'student'
                WHEN title LIKE '%worker%' THEN 'worker'
                WHEN title LIKE '%spouse%' THEN 'spouse'
                WHEN title LIKE '%dependant%' THEN 'dependant'
                WHEN title LIKE '%CF%' OR title LIKE '%Canadian Forces%' THEN 'military'
                WHEN title LIKE '%RCMP%' THEN 'RCMP'
                WHEN title LIKE '%diplomat%' THEN 'diplomat'
                ELSE 'general'
            END as population_type
        FROM act_eligibility_rule;
CREATE VIEW v_act_all_rules AS
        SELECT 
            'eligibility' as rule_type,
            section_ref,
            title,
            effect,
            line_range
        FROM act_eligibility_rule
        UNION ALL
        SELECT 
            'status_extension' as rule_type,
            section_ref,
            population as title,
            effect,
            line_range
        FROM act_status_extension
        UNION ALL
        SELECT 
            'dependant_carryover' as rule_type,
            section_ref,
            who || ' of ' || anchor_population as title,
            effect,
            line_range
        FROM act_dependant_carryover
        UNION ALL
        SELECT 
            'health_card' as rule_type,
            section_ref,
            obligation as title,
            scope as effect,
            line_range
        FROM act_health_card_rule
        UNION ALL
        SELECT 
            'uninsured' as rule_type,
            act_pointer as section_ref,
            exemplar as title,
            schedule_pointer as effect,
            line_range
        FROM act_uninsured_reference;
CREATE INDEX idx_act_eligibility_topics ON act_eligibility_rule(title);
CREATE INDEX idx_adp_funding_rule_doc ON adp_funding_rule(adp_doc, scenario);
CREATE INDEX idx_adp_exclusion_phrase ON adp_exclusion(phrase);
CREATE INDEX idx_adp_exclusion_doc ON adp_exclusion(adp_doc, applies_to);
CREATE TRIGGER update_adp_funding_rule_timestamp
AFTER UPDATE ON adp_funding_rule
BEGIN
  UPDATE adp_funding_rule SET updated_at = CURRENT_TIMESTAMP WHERE rule_id = NEW.rule_id;
END;
CREATE TRIGGER update_adp_exclusion_timestamp
AFTER UPDATE ON adp_exclusion
BEGIN
  UPDATE adp_exclusion SET updated_at = CURRENT_TIMESTAMP WHERE exclusion_id = NEW.exclusion_id;
END;
COMMIT;
